static int tun_ptr_ring_resize(struct ptr_ring **rings, int nrings,
			       int size, gfp_t gfp, void (*destroy)(void *))
{
	unsigned long flags;
	void **dropped = NULL;
	void ***queues;
	int i, n, err = 0;

	queues = kmalloc_array(nrings, sizeof(*queues), gfp);
	if (!queues)
		return -ENOMEM;

	for (i = 0; i < nrings; ++i)
		queues[i] = NULL;

	for (i = 0; i < nrings; ++i) {
		queues[i] = __ptr_ring_init_queue_alloc(size, gfp);
		if (!queues[i]) {
			err = -ENOMEM;
			goto nomem;
		}
	}

	if (nrings > 0) {
		int max_old_size = 0;
		for (i = 0; i < nrings; ++i) {
			if (rings[i]->size > max_old_size)
				max_old_size = rings[i]->size;
		}
		if (max_old_size > 0) {
			dropped = kmalloc_array(max_old_size, sizeof(void *), gfp);
			if (!dropped) {
				err = -ENOMEM;
				goto nomem;
			}
		}
	}

	for (i = 0; i < nrings; ++i) {
		struct ptr_ring *r = rings[i];
		void **new_queue = queues[i];
		void **old_queue;
		void *ptr;
		int producer = 0;
		int dropped_cnt = 0;

		spin_lock_irqsave(&(r)->consumer_lock, flags);
		spin_lock(&(r)->producer_lock);

		while ((ptr = __ptr_ring_consume(r))) {
			if (producer < size)
				new_queue[producer++] = ptr;
			else if (dropped)
				dropped[dropped_cnt++] = ptr;
		}

		if (producer >= size)
			producer = 0;
		__ptr_ring_set_size(r, size);
		r->producer = producer;
		r->consumer_head = 0;
		r->consumer_tail = 0;
		old_queue = r->queue;
		r->queue = new_queue;

		spin_unlock(&(r)->producer_lock);
		spin_unlock_irqrestore(&(r)->consumer_lock, flags);

		kvfree(old_queue);

		if (destroy && dropped) {
			for (n = 0; n < dropped_cnt; ++n)
				destroy(dropped[n]);
		}
	}

	kfree(dropped);
	kfree(queues);
	return 0;

nomem:
	if (dropped)
		kfree(dropped);
	for (i = 0; i < nrings; ++i)
		kvfree(queues[i]);
	kfree(queues);
	return err;
}

